import{_ as t,o as s,c as e,a5 as n}from"./chunks/framework.DGp912Ge.js";const p=JSON.parse('{"title":"화재 및 열 주의사항","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/fire-and-heat-precautions.md","filePath":"ko/manual/safety/fire-and-heat-precautions.md","lastUpdated":1785806273000}'),r={name:"ko/manual/safety/fire-and-heat-precautions.md"};function o(i,a,l,d,c,u){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="화재-및-열-주의사항" tabindex="-1">화재 및 열 주의사항 <a class="header-anchor" href="#화재-및-열-주의사항" aria-label="Permalink to &quot;화재 및 열 주의사항&quot;">​</a></h1><p>RBQ 및 충전기·배터리를 사용할 때 화재·화상·과열을 방지하기 위한 사항입니다.</p><h2 id="열·접촉" tabindex="-1">열·접촉 <a class="header-anchor" href="#열·접촉" aria-label="Permalink to &quot;열·접촉&quot;">​</a></h2><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>1) 로봇 본체와 제어기는 장시간 사용 시 열이 납니다. 운용 중이거나 직후에는 만지지 마세요. 접촉 전 최소 1시간 정도 식힌 후, UI 온도 표시를 확인하거나 전원을 끄고 식혀 두세요.<br>2) 충전 중인 배터리·충전기·도킹 스테이션도 뜨거울 수 있으므로, 충전 중에는 가연성 물체를 가까이 두지 마세요.</p></div></div><ul><li><strong>환기</strong>: 제어기·충전기는 환기가 잘 되는 곳에 두고, 덮개나 옷으로 가리지 마세요. 과열은 고장·화재의 원인이 됩니다.</li></ul><h2 id="화재-예방" tabindex="-1">화재 예방 <a class="header-anchor" href="#화재-예방" aria-label="Permalink to &quot;화재 예방&quot;">​</a></h2><ul><li><strong>가연성 물질</strong>: 로봇·충전기 주변에 종이, 천, 솔벤트 등 가연성 물질을 두지 마세요.</li><li><strong>배터리</strong>: 배터리를 불에 가까이 하거나, 찌그러뜨리거나, 구멍을 내지 마세요. 손상된 배터리는 사용하지 말고 안전하게 폐기하세요.</li><li><strong>충전</strong>: 지정된 충전기만 사용하고, 손상된 케이블·충전기는 사용하지 마세요. <a href="/RBQ/ko/manual/safety/battery-handling.html">배터리 취급 주의사항</a>을 함께 참고하세요.</li></ul><h2 id="이상-시-조치" tabindex="-1">이상 시 조치 <a class="header-anchor" href="#이상-시-조치" aria-label="Permalink to &quot;이상 시 조치&quot;">​</a></h2><ul><li><strong>연기·냄새</strong>: 연기나 이상한 냄새가 나면 즉시 전원을 끄고, 플러그를 뽑은 뒤 <strong>안전한 거리로 대피</strong>하세요.</li></ul><div class="sb sb-danger"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">위험</p><p><strong>화재 시</strong>: RBQ·충전기·배터리에서 화재가 발생하면 <strong>직접 진화를 시도하지 마세요.</strong> 인명 안전을 우선으로 <strong>대피한 뒤</strong> 소방 대응을 요청하세요. 리튬 배터리 등은 일반 소화기나 물로는 완전히 끄기 어렵거나 오히려 위험할 수 있으므로, 전기·전자 제품용(가스·분말 등) 소화기가 권장됩니다.</p></div></div><ul><li><strong>과열 알람</strong>: 제품이나 GUI에서 과열 경고가 나오면 사용을 중단하고 식힌 뒤, 매뉴얼 또는 Rainbow Robotics에 문의하세요.</li></ul>',11)])])}const b=t(r,[["render",o]]);export{p as __pageData,b as default};
